import 'package:url_launcher/url_launcher.dart';

enum ContactCategory { bugReport, featureRequest, calculationIssue, generalFeedback }
extension ContactCategoryText on ContactCategory { String get label=>switch(this){ContactCategory.bugReport=>'Bug Report',ContactCategory.featureRequest=>'Feature Request',ContactCategory.calculationIssue=>'Calculation Issue',ContactCategory.generalFeedback=>'General Feedback'}; String get subject=>switch(this){ContactCategory.bugReport=>'SiteQuant Bug Report',ContactCategory.featureRequest=>'SiteQuant Feature Suggestion',ContactCategory.calculationIssue=>'SiteQuant Calculation Issue',ContactCategory.generalFeedback=>'SiteQuant Feedback'}; }
abstract interface class ContactEmailLauncher { Future<bool> launch(Uri uri); }
class UrlContactEmailLauncher implements ContactEmailLauncher { const UrlContactEmailLauncher(); @override Future<bool> launch(Uri uri)=>launchUrl(uri,mode:LaunchMode.externalApplication); }
class ContactDeveloperService { static const email='sitequantapp@gmail.com'; final ContactEmailLauncher launcher; const ContactDeveloperService({this.launcher=const UrlContactEmailLauncher()}); Uri compose({required ContactCategory category,String? name,String? senderEmail,required String message,String version='1.0.0+4'})=>Uri(scheme:'mailto',path:email,queryParameters:{'subject':category.subject,'body':'Category: ${category.label}\n${name?.trim().isNotEmpty==true?'Name: ${name!.trim()}\n':''}${senderEmail?.trim().isNotEmpty==true?'Email: ${senderEmail!.trim()}\n':''}App version: $version\n\nMessage:\n${message.trim()}'}); Future<bool> open({required ContactCategory category,String? name,String? senderEmail,required String message})=>launcher.launch(compose(category:category,name:name,senderEmail:senderEmail,message:message)); }
